{
  "root_causes": [
    {
      "service": "ts-inside-payment-service",
      "fault_kind": "application_exception",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n, quantile_cont(duration,0.5)/1e6 AS med_ms FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND attr_span_kind='Server' GROUP BY 1,2,3,4 ORDER BY n DESC",
          "claim": "Every abnormal inside_payment server span returns HTTP 500 with Error status, about 10 ms each, roughly 2000 spans."
        },
        {
          "kind": "log",
          "sql": "SELECT level, attr_log_template, count(*) AS n FROM abnormal_logs WHERE service_name='ts-inside-payment-service' AND level IN ('SEVERE','ERROR') GROUP BY 1,2 ORDER BY n DESC",
          "claim": "SEVERE dispatcher exception 'Request processing failed ... IllegalArgumentException: URI is not absolute' logged 2000 times, with no matching normal-period errors."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, quantile_cont(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name LIKE 'Transaction%' OR (service_name='ts-inside-payment-service' AND span_name LIKE '%Pay%') GROUP BY 1",
          "claim": "Inside-payment's pay handler fails before any outbound call; calls to order and payment services disappear in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, avg(value) v, max(value) mx FROM abnormal_metrics WHERE service_name='ts-inside-payment-service' AND metric IN ('queueSize','k8s.pod.cpu_limit_utilization') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value), max(value) FROM normal_metrics WHERE service_name='ts-inside-payment-service' AND metric IN ('queueSize','k8s.pod.cpu_limit_utilization') GROUP BY 1,2",
          "claim": "queueSize rose from 0 to about 26.5 (max 72) while CPU limit utilization stayed well below saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, c.duration/1e6 AS ms FROM abnormal_traces c WHERE c.trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%inside_payment%' AND attr_span_kind='Server' LIMIT 1) ORDER BY c.time",
          "claim": "ui-dashboard retries the failing inside_payment call about ten times, each answered with a 500 in about 10 ms, so its own span takes 0.8–1.5 s."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n, quantile_cont(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%inside_payment%' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "ui-dashboard's inside_payment spans are Error in 114 cases with p95 about 4 s, versus normal Unset status."
        }
      ]
    }
  ]
}
```

